<?php /** @var array $plan */ ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= htmlspecialchars((string)$plan['name']) ?> · EduSasa</title><style>body{font-family:system-ui,sans-serif;margin:0;background:#f5f7fb;color:#172033}main{max-width:1200px;margin:auto;padding:28px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px;margin-bottom:18px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #eee}input{width:100%;box-sizing:border-box;padding:9px;border:1px solid #d0d5dd;border-radius:8px}button{padding:9px 14px;border:0;border-radius:8px;background:#172033;color:#fff}.muted{color:#667085}</style></head><body><main><h1><?= htmlspecialchars((string)$plan['name']) ?></h1><p class="muted"><?= htmlspecialchars((string)($plan['description']??'')) ?></p><div class="card"><form method="post" action="/platform/plans/<?= (int)$plan['id'] ?>"><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><label>Code<input name="code" value="<?= htmlspecialchars((string)$plan['code']) ?>"></label><label>Name<input name="name" value="<?= htmlspecialchars((string)$plan['name']) ?>"></label><label>Price<input name="price" type="number" step="0.01" value="<?= htmlspecialchars((string)$plan['price']) ?>"></label><label>Billing interval<input name="billing_interval" value="<?= htmlspecialchars((string)$plan['billing_interval']) ?>"></label></div><p><label><input type="checkbox" name="is_active" value="1" <?= !empty($plan['is_active'])?'checked':'' ?>> Active</label></p><button>Save plan</button></form></div><div class="card"><h2>Feature entitlements</h2><table><thead><tr><th>Module</th><th>Feature</th><th>Enabled</th><th>Limits JSON</th><th>Save</th></tr></thead><tbody><?php foreach($plan['features'] as $f): ?><tr><td><?= htmlspecialchars((string)$f['module_code']) ?></td><td><?= htmlspecialchars((string)$f['name']) ?><br><small><?= htmlspecialchars((string)$f['code']) ?></small></td><td><input id="enabled<?= (int)$f['id'] ?>" type="checkbox" <?= $f['limits_json']!==null?'checked':'' ?>></td><td><input id="limits<?= (int)$f['id'] ?>" value="<?= htmlspecialchars((string)($f['limits_json']??'')) ?>" placeholder='{"max":100}'></td><td><button type="button" onclick="saveFeature(<?= (int)$plan['id'] ?>,<?= (int)$f['id'] ?>)">Save</button></td></tr><?php endforeach; ?></tbody></table></div></main><script>async function saveFeature(plan,feature){const enabled=document.getElementById('enabled'+feature).checked;let limits=document.getElementById('limits'+feature).value;let parsed=null;if(limits.trim()){try{parsed=JSON.parse(limits)}catch(e){alert('Limits must be valid JSON');return}}const r=await fetch('/platform/plans/'+plan+'/features/'+feature,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled,limits:parsed})});const d=await r.json();if(!d.success)alert(d.message||'Unable to save');else location.reload()}</script></body></html>
